/**
 * Rating (spec/02 §3.20, D82): one filled star (20 dp, in text), the value with its reference in bodyStrong
 * („4,2 von 5“: [value] with one decimal in the screen's language, of [max]) and „· 38 Bewertungen“ ([count]) in body
 * textMuted, tabular figures, 4 dp apart; the count wraps under the value. Never five stars, half stars or a yellow
 * star. One TalkBack node „Bewertung: 4,2 von 5, 38 Bewertungen“.
 */
@Composable
fun SbRating(value: Float, count: Int, modifier: Modifier = Modifier, max: Int = 5) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val m = sbMessages()
    val locale = sbAppLocale()
    val number = remember(value, locale) {
        NumberFormat.getNumberInstance(locale).apply {
            minimumFractionDigits = 1
            maximumFractionDigits = 1
        }.format(value)
    }
    val of = m.ratingOf(number, sbFormatCount(max))
    val counted = m.ratingCount(count, sbFormatCount(count))
    val tabular = ty.numeric.fontFeatureSettings
    SbFlowRow(
        modifier.clearAndSetSemantics { contentDescription = m.ratingLabel + of + ", " + counted },
        horizontalArrangement = Arrangement.spacedBy(t.space.s1),
    ) {
        Icon(
            SebaroIcons.Filled.Star,
            contentDescription = null,
            tint = c.text,
            modifier = Modifier.align(Alignment.CenterVertically).size(t.size.iconMd),
        )
        Text(of, style = ty.bodyStrong.copy(fontFeatureSettings = tabular), color = c.text)
        Text("· $counted", style = ty.body.copy(fontFeatureSettings = tabular), color = c.textMuted)
    }
}
